import{_ as a,o as n,c as i,a5 as o}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"07 — Publishing & Social + Third-party Collaborator (mở rộng mới)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/07-publishing-social-collaborator.md","filePath":"ba/07-publishing-social-collaborator.md"}'),h={name:"ba/07-publishing-social-collaborator.md"};function r(l,t,c,e,g,s){return n(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="_07-—-publishing-social-third-party-collaborator-mo-rong-moi" tabindex="-1">07 — Publishing &amp; Social + Third-party Collaborator (mở rộng mới) <a class="header-anchor" href="#_07-—-publishing-social-third-party-collaborator-mo-rong-moi" aria-label="Permalink to &quot;07 — Publishing &amp; Social + Third-party Collaborator (mở rộng mới)&quot;">​</a></h1><p>&gt; <a href="./00-overview.html">&lt;&lt; Về Overview</a></p><h2 id="_1-publishing-social-fr-3-8-1-–-3-8-16-—-tu-đong-qua-api" tabindex="-1">1. Publishing &amp; Social (FR 3.8.1 – 3.8.16) — tự động qua API <a class="header-anchor" href="#_1-publishing-social-fr-3-8-1-–-3-8-16-—-tu-đong-qua-api" aria-label="Permalink to &quot;1. Publishing &amp; Social (FR 3.8.1 – 3.8.16) — tự động qua API&quot;">​</a></h2><h3 id="ket-noi-ngat-tai-khoan" tabindex="-1">Kết nối/ngắt tài khoản <a class="header-anchor" href="#ket-noi-ngat-tai-khoan" aria-label="Permalink to &quot;Kết nối/ngắt tài khoản&quot;">​</a></h3><ul><li><strong>Connect Social Account</strong> (3.8.1): kết nối tài khoản để Client login vào toàn bộ tài khoản đăng bài tự động. Role: CLIENT.</li><li><strong>Disconnect Account</strong> (3.8.2): ngắt kết nối, log out khỏi mạng xã hội. Role: CLIENT.</li></ul><h3 id="dashboard-tracking" tabindex="-1">Dashboard &amp; tracking <a class="header-anchor" href="#dashboard-tracking" aria-label="Permalink to &quot;Dashboard &amp; tracking&quot;">​</a></h3><ul><li><strong>View Dashboard Post</strong> (3.8.3): trang tổng quan trong workspace khi đăng thành công lên social. Role: MEMBER.</li><li><strong>View Post Track Detail</strong> (3.8.4): chi tiết bài đăng — reaction, comment, share count. Role: MEMBER.</li><li><strong>View Comment Detail List</strong> (3.8.5): danh sách chi tiết comment từ bài post. Role: MEMBER.</li><li><strong>Preview Post</strong> (3.8.6): xem trước layout theo từng mạng xã hội khi Creator sửa/làm bài. Role: MEMBER.</li><li><strong>Schedule Platform Post</strong> (3.8.7): trang lịch đăng bài, xem theo lịch cụ thể. Role: MEMBER.</li><li><strong>View Status Tracking</strong> (3.8.8): theo dõi tiến độ — Pending, In Progress, Done, Fail. Role: MEMBER.</li></ul><h3 id="publish-theo-tung-platform-3-8-9-–-3-8-16" tabindex="-1">Publish theo từng platform (3.8.9 – 3.8.16) <a class="header-anchor" href="#publish-theo-tung-platform-3-8-9-–-3-8-16" aria-label="Permalink to &quot;Publish theo từng platform (3.8.9 – 3.8.16)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>FR</th><th>Platform + loại content</th></tr></thead><tbody><tr><td>3.8.9</td><td>Publish Facebook Post</td></tr><tr><td>3.8.10</td><td>Publish Facebook Story</td></tr><tr><td>3.8.11</td><td>Publish Facebook Reels</td></tr><tr><td>3.8.12</td><td>Publish Instagram Post</td></tr><tr><td>3.8.13</td><td>Publish Instagram Reels</td></tr><tr><td>3.8.14</td><td>Publish Instagram Story</td></tr><tr><td>3.8.15</td><td>Publish TikTok Video</td></tr><tr><td>3.8.16</td><td>Publish Threads Post</td></tr></tbody></table><p>Tất cả role: MEMBER. Đây là hàng đợi Publish nhận Task loại <strong>Post</strong> đã hoàn thành Approval Sequence (xem <a href="./05-content-task-workflow.html">05-content-task-workflow.md</a> mục 4).</p><p><strong>Lưu ý phạm vi</strong>: nhóm FR này giữ nguyên các platform social hiện có (Facebook, Instagram, TikTok, Threads) — KHÔNG có Zalo OA (đã loại khỏi scope theo quyết định trước — xem lịch sử session, không thuộc phạm vi tài liệu BA này).</p><h2 id="_2-third-party-collaborator-—-module-mo-rong-moi-chua-co-trong-csv-goc-xac-nhan-qua-hoi-đap" tabindex="-1">2. Third-party Collaborator — module MỞ RỘNG mới (chưa có trong CSV gốc, xác nhận qua hỏi-đáp) <a class="header-anchor" href="#_2-third-party-collaborator-—-module-mo-rong-moi-chua-co-trong-csv-goc-xac-nhan-qua-hoi-đap" aria-label="Permalink to &quot;2. Third-party Collaborator — module MỞ RỘNG mới (chưa có trong CSV gốc, xác nhận qua hỏi-đáp)&quot;">​</a></h2><p><strong>[CONFIRMED 2026-09-14]</strong> Đây là điểm mở rộng nghiệp vụ lớn nhất ngoài phạm vi social media — phản ánh yêu cầu &quot;mở rộng một chiến dịch truyền thông số rộng hơn, có tính lan tỏa nhiều hơn qua nhiều phương tiện truyền thông khác nhau&quot; của Trung.</p><h3 id="van-đe" tabindex="-1">Vấn đề <a class="header-anchor" href="#van-đe" aria-label="Permalink to &quot;Vấn đề&quot;">​</a></h3><ul><li>FR 3.7.12 (Recommend Collaborator) chỉ gợi ý AI cho đối tác truyền thông ngoài social media: <strong>báo điện tử, đối tác chạy banner, kênh TV</strong>.</li><li>Các đối tác này <strong>không có API</strong> như Facebook/TikTok — không thể tự động hóa đăng bài.</li><li>Nhưng Agency vẫn cần <strong>theo dõi trạng thái hợp tác</strong> với các đối tác đó như 1 phần của Media Campaign.</li></ul><h3 id="giai-phap-đa-chot" tabindex="-1">Giải pháp đã chốt <a class="header-anchor" href="#giai-phap-đa-chot" aria-label="Permalink to &quot;Giải pháp đã chốt&quot;">​</a></h3><ul><li>Cần <strong>1 module/entity riêng</strong> — &quot;Third-party Collaborator&quot; (tên đề xuất, chưa chốt chính thức) — để lưu: <ul><li>Thông tin liên hệ đối tác (tên báo/đài/đơn vị chạy banner, người liên hệ, kênh liên hệ).</li><li>Trạng thái hợp tác: <strong>đã liên hệ → đang đàm phán → đã chốt → đã lên sóng</strong>.</li></ul></li><li><strong>Không tự động hóa đăng bài</strong> lên các kênh này — chỉ là tracking thủ công do Manager/Creator cập nhật tay.</li><li>Gắn với <strong>Media Campaign hoặc Task cụ thể</strong> — 1 Campaign có thể có nhiều Collaborator khác nhau.</li><li>AI Recommend Collaborator (FR 3.7.12, xem <a href="./06-ai-features.html">06-ai-features.md</a>) chỉ đưa ra gợi ý ứng viên ban đầu — không tác động vào trạng thái hợp tác.</li></ul><h3 id="viec-can-lam-tiep-chua-thiet-ke-chi-tiet" tabindex="-1">Việc CẦN LÀM tiếp (chưa thiết kế chi tiết) <a class="header-anchor" href="#viec-can-lam-tiep-chua-thiet-ke-chi-tiet" aria-label="Permalink to &quot;Việc CẦN LÀM tiếp (chưa thiết kế chi tiết)&quot;">​</a></h3><p>&gt; <strong>Xác nhận người dùng 2026-10-13:</strong> E50-08 / DA-949 là danh bạ cấp Agency, chỉ Owner quản lý. Đối tác chưa từng được Campaign dùng có thể xóa; đã dùng chỉ ngừng sử dụng, không được gán mới. Campaign đã liên kết vẫn xem và cập nhật hợp tác theo E50-09 / DA-950. Entity/schema V2 đã có; phần mô tả “chưa có schema” bên dưới là lịch sử. Thiết kế hiện hành: <code>docs/feature/media-package-campaign/partner-directory/spec.md</code>. Không mở rộng sang AI/booking/thanh toán. Cần lead/team review thông tin BA chung.</p><ul><li>Chưa có entity/DB schema chính thức cho Third-party Collaborator — cần thiết kế field cụ thể (tên đối tác, loại kênh, chi phí, người phụ trách, ghi chú, trạng thái, lịch sử thay đổi trạng thái...).</li><li>Chưa có FR số hiệu chính thức trong CSV — đây là module PHÁT SINH ngoài 109 FR gốc, cần bổ sung số FR mới khi cập nhật CSV chính thức (đề xuất: nhóm vào 3.8, ví dụ 3.8.17 – 3.8.2x, hoặc nhóm riêng 3.11 &quot;Third-party Media Collaboration&quot;).</li></ul>',20)])])}const m=a(h,[["render",r]]);export{u as __pageData,m as default};
